example_item.example_item_data:
new_system('sig');
add_block('nflow/source/sine', 'sig/Src');
add_block('nflow/math/gain', 'sig/K', 'Gain', 2);
add_block('nflow/sink/scope', 'sig/Scope');
add_line('sig', 'Src/1', 'K/1');      % numbered: signal port 1 -> 1
add_line('sig', 'K/1', 'Scope/1');
set_param('sig', 'StopTime', 10, 'SampleTime', 0.01, 'Solver', 'discrete');
nflow_layout('sig');
f = [tempdir(), 'sig.nflow'];
save_system('sig', f);
bdclose('sig');
out = sim(f, 'StopTime', 10);

new_system('rlc');
add_block('nflow/acausal_electrical/ConstantVoltage', 'rlc/V1', 'V', 1);
add_block('nflow/acausal_electrical/Resistor', 'rlc/R1', 'R', 1);
add_block('nflow/acausal_electrical/Inductor', 'rlc/L1', 'L', 1, 'i0', 0);
add_block('nflow/acausal_electrical/Capacitor', 'rlc/C1', 'C', 1, 'v0', 0);
add_block('nflow/acausal_electrical/VoltageSensor', 'rlc/VS');
add_block('nflow/acausal_electrical/Ground', 'rlc/G1');
add_block('nflow/acausal_electrical/Ground', 'rlc/G2');
add_block('nflow/sink/scope', 'rlc/Scope');
add_line('rlc', 'V1/p', 'R1/p');      % named pins: physical joints
add_line('rlc', 'R1/n', 'L1/p');
add_line('rlc', 'L1/n', 'C1/p');      % node L1.n-C1.p ...
add_line('rlc', 'C1/p', 'VS/p');      % ... VS.p merges into it
add_line('rlc', 'G1/p', 'V1/n');
add_line('rlc', 'C1/n', 'VS/n');      % node C1.n-VS.n ...
add_line('rlc', 'G2/p', 'C1/n');      % ... G2.p merges into it
add_line('rlc', 'VS/1', 'Scope/1');   % numbered: sensor signal output
set_param('rlc', 'StopTime', 10, 'SampleTime', 0.05, 'Solver', 'dae');
nflow_layout('rlc');
f = [tempdir(), 'rlc.nflow'];
save_system('rlc', f);
bdclose('rlc');
out = sim(f, 'StopTime', 10);
